    /* About Dialog */
    "dlg.about.title": {
      en: "About Solacut",
      zh: "关于 Solacut",
      ja: "Solacut について",
      ko: "Solacut 정보",
      ru: "О Solacut",
      es: "Acerca de Solacut",
    },
    "dlg.about.subtitle": {
      en: "Local-first assistant editor & 6-language localization workbench for NLE round-trip",
      zh: "纯本地助理剪辑师与六语种审校工作台（原生对接 DaVinci / Premiere / FCP）",
      ja: "完全ローカルのアシスタント編集＆6言語ローカライズ作業台（DaVinci / Premiere / FCP連携）",
      ko: "로컬 어시스턴트 편집 및 6개 언어 번역 검수 워크벤치 (DaVinci / Premiere / FCP 연동)",
      ru: "Локальный ассистент монтажа и студия локализации на 6 языков (DaVinci / Premiere / FCP)",
      es: "Asistente de edición local y mesa de localización en 6 idiomas (DaVinci / Premiere / FCP)",
    },
    "dlg.about.listHtml": {
      en: "<li><strong>License</strong>: MIT License (100% local, free, zero telemetry)</li><li><strong>Languages</strong>: EN / ZH / JA / KO / RU / ES 6×6 pairs + 228,210 commercial-safe corpus pairs</li><li><strong>Security</strong>: 127.0.0.1 loopback + 256-bit session token + CSRF / DNS Rebinding isolation</li><li><strong>Website</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>Repository</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      zh: "<li><strong>开源协议</strong>：MIT License（纯本地免费、零强制联网、零遥测）</li><li><strong>语料支持</strong>：中 / 英 / 日 / 韩 / 俄 / 西 6 语种自由组合 + 228,210 条商用语料底座</li><li><strong>安全架构</strong>：127.0.0.1 回环绑定 + 256-bit 会话令牌 + 防跨站/DNS Rebinding 隔离</li><li><strong>官方网站</strong>：<a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>开源仓库</strong>：<a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      ja: "<li><strong>ライセンス</strong>: MIT License（完全ローカル無料・テレメトリゼロ）</li><li><strong>対応言語</strong>: 英/中/日/韓/露/西 6×6自由組合せ + 商用可228,210対訳コーパス</li><li><strong>セキュリティ</strong>: 127.0.0.1限定 + 256-bitセッショントークン + DNS Rebinding防御</li><li><strong>公式サイト</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>リポジトリ</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      ko: "<li><strong>라이선스</strong>: MIT License (100% 로컬 무료, 텔레메트리 없음)</li><li><strong>언어 지원</strong>: 영/중/일/한/러/스 6×6 자유 조합 + 상업용 228,210 병렬 코퍼스</li><li><strong>보안 아키텍처</strong>: 127.0.0.1 루프백 + 256비트 세션 토큰 + CSRF/DNS 리바인딩 차단</li><li><strong>공식 사이트</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>오픈소스 저장소</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      ru: "<li><strong>Лицензия</strong>: MIT License (полностью локально, бесплатно, без телеметрии)</li><li><strong>Языки</strong>: EN / ZH / JA / KO / RU / ES (6×6 пар) + 228 210 коммерческих пар корпуса</li><li><strong>Безопасность</strong>: привязка к 127.0.0.1 + 256-битный токен + защита от CSRF / DNS Rebinding</li><li><strong>Сайт</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>Репозиторий</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      es: "<li><strong>Licencia</strong>: MIT License (100% local, gratis, cero telemetría)</li><li><strong>Idiomas</strong>: EN / ZH / JA / KO / RU / ES (6×6) + 228.210 pares de corpus comercial</li><li><strong>Seguridad</strong>: enlace 127.0.0.1 + token de 256 bits + protección CSRF / DNS Rebinding</li><li><strong>Sitio web</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>Repositorio</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
    },

